function getMoneyAmount(n) {
  const dp = Array.from({ length: n + 2 }, () => new Array(n + 2).fill(0));
  for (let length = 2; length <= n; length++) {
    for (let low = 1; low + length - 1 <= n; low++) {
      const high = low + length - 1;
      let best = Infinity;
      for (let guess = low; guess <= high; guess++) {
        const worst = guess + Math.max(dp[low][guess - 1], dp[guess + 1][high]);
        best = Math.min(best, worst);
      }
      dp[low][high] = best;
    }
  }
  return dp[1][n];
}

