function getMoneyAmount(n) {
  const memo = new Map();
  const cost = (lo, hi) => {
    if (lo >= hi) return 0;
    const key = lo * 1000 + hi;
    if (memo.has(key)) return memo.get(key);
    let answer = Number.MAX_SAFE_INTEGER;
    for (let x = lo; x <= hi; x++) {
      const below = cost(lo, x - 1);
      const above = cost(x + 1, hi);
      answer = Math.min(answer, x + (below > above ? below : above));
    }
    memo.set(key, answer);
    return answer;
  };
  return cost(1, n);
}

